#!/usr/bin/env python3
"""Emit one Linux kernel random-pool and readiness sample as compact JSON."""
import datetime
import errno
import json
import os
import platform
import time
from pathlib import Path

SCHEMA_VERSION = 1
COLLECTOR = "linux_kernel_random_v1"
RANDOM_SYSCTL = Path("/proc/sys/kernel/random")


def read_text(name):
    return (RANDOM_SYSCTL / name).read_text(encoding="ascii").strip()


def read_integer(name):
    value = int(read_text(name), 10)
    if value < 0:
        raise ValueError(name + "_negative")
    return value


def probe_rng():
    if not hasattr(os, "getrandom") or not hasattr(os, "GRND_NONBLOCK"):
        return "unsupported", errno.ENOSYS
    try:
        os.getrandom(1, os.GRND_NONBLOCK)
        return "ready", None
    except BlockingIOError as error:
        return "not_ready", error.errno
    except NotImplementedError:
        return "unsupported", errno.ENOSYS
    except OSError as error:
        if error.errno == errno.ENOSYS:
            return "unsupported", error.errno
        return "probe_error", error.errno


def main():
    sample_epoch = int(time.time())
    event = {
        "event_time": datetime.datetime.fromtimestamp(sample_epoch, datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
        "schema_version": SCHEMA_VERSION,
        "collector": COLLECTOR,
        "collector_status": "ok",
        "sample_epoch": sample_epoch,
        "kernel_release": platform.release(),
    }
    try:
        entropy_avail_bits = read_integer("entropy_avail")
        poolsize_bits = read_integer("poolsize")
        boot_id = read_text("boot_id")
        uptime_seconds = float(Path("/proc/uptime").read_text(encoding="ascii").split()[0])
        if not boot_id or poolsize_bits <= 0 or entropy_avail_bits > poolsize_bits or uptime_seconds < 0:
            raise ValueError("invalid_kernel_random_values")
        probe_status, probe_errno = probe_rng()
        if probe_status == "probe_error":
            event["collector_status"] = "partial"
        event.update(
            boot_id=boot_id,
            uptime_seconds=round(uptime_seconds, 3),
            entropy_avail_bits=entropy_avail_bits,
            poolsize_bits=poolsize_bits,
            rng_probe_status=probe_status,
            probe_errno=probe_errno,
        )
    except (OSError, UnicodeError, ValueError, IndexError) as error:
        event.update(
            collector_status="read_error",
            rng_probe_status="not_attempted",
            error_type=type(error).__name__,
            error_errno=getattr(error, "errno", None),
        )
    print(json.dumps(event, separators=(",", ":"), sort_keys=True), flush=True)


if __name__ == "__main__":
    main()
